#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""SIREN Zen Garden rework installer - palette + ambient scene + intro, in one pass.

Usage:  python install_zen.py <target.html>

Self-contained (all payloads embedded, base64) and idempotent: each of the
three parts is skipped if already applied. Every anchor is located in the
current file content and its count asserted; on any mismatch the script
aborts WITHOUT writing. After a successful write, every inline <script> in
the result is syntax-checked with `node --check`; a syntax failure restores
the original file.

Parts:
  1. PALETTE  - [data-theme="zen"] token block, zen surface rules (raked comb
                grain + vermilion header beam), ambient glass tints,
                themePresets.zen (Mermaid), theme-menu swatch.
  2. SCENE    - the AMBIENT_SCENES zen entry is replaced structurally: from
                "zen: { settleFrames:" inside AMBIENT_SCENES walk back to its
                /* comment */ and forward to its closing "        }," (a
                trailing-comma-less last entry is accepted too).
  3. INTRO    - #zenIntroOverlay markup (up to the koi overlay marker) and the
                .zen-intro-overlay CSS block are replaced whole.
"""
import base64
import io
import os
import re
import subprocess
import sys
import tempfile


def b64(s):
    return base64.b64decode(s).decode("utf-8")


PAL_OLD_TOKENS = b64("")
PAL_NEW_TOKENS = b64("")
PAL_OLD_AMBIENT = b64("W2RhdGEtdGhlbWU9InplbiJdICAgICAgIHsgLS1hbWJpZW50LW9wYWNpdHk6IC45NTsgLS1hbWJpZW50LWNhcmQ6IHJnYmEoMjQ1LCAyNDAsIDIyNywgLjYpOyAtLWFtYmllbnQtYmFyOiByZ2JhKDI0NSwgMjQwLCAyMjcsIC43NCk7IC0tYW1iaWVudC1wYW5lOiByZ2JhKDI0NSwgMjQwLCAyMjcsIC42OCk7IH0=")
PAL_NEW_AMBIENT = b64("W2RhdGEtdGhlbWU9InplbiJdICAgICAgIHsgLS1hbWJpZW50LW9wYWNpdHk6IC45NTsgLS1hbWJpZW50LWNhcmQ6IHJnYmEoMjQ2LCAyNDMsIDIzNCwgLjYpOyAtLWFtYmllbnQtYmFyOiByZ2JhKDI0NiwgMjQzLCAyMzQsIC43NCk7IC0tYW1iaWVudC1wYW5lOiByZ2JhKDI0NiwgMjQzLCAyMzQsIC42OCk7IH0=")
PAL_OLD_PRESET = b64("")
PAL_NEW_PRESET = b64("")
PAL_OLD_SWATCH = b64("ZGF0YS10aGVtZS12YWx1ZT0iemVuIiBhcmlhLXNlbGVjdGVkPSJmYWxzZSI+PHNwYW4gY2xhc3M9InRoZW1lLW9wdGlvbi1zd2F0Y2giIHN0eWxlPSItLXN3YXRjaC1hOiNlY2U1ZDM7LS1zd2F0Y2gtYjojNGE1ZDQzIg==")
PAL_NEW_SWATCH = b64("ZGF0YS10aGVtZS12YWx1ZT0iemVuIiBhcmlhLXNlbGVjdGVkPSJmYWxzZSI+PHNwYW4gY2xhc3M9InRoZW1lLW9wdGlvbi1zd2F0Y2giIHN0eWxlPSItLXN3YXRjaC1hOiNlYWU2ZGE7LS1zd2F0Y2gtYjojNDU2NjNhIg==")
SCENE = b64("")
INTRO_HTML = b64("")
INTRO_CSS = b64("")


def die(msg):
    sys.stderr.write("ABORT: %s - nothing written\n" % msg)
    sys.exit(1)


def swap(text, old, new, label):
    """Replace old->new exactly once; tolerate an already-applied patch."""
    n = text.count(old)
    if n == 1:
        print("  + %s" % label)
        return text.replace(old, new, 1)
    if n == 0 and new in text:
        print("  = %s: already applied" % label)
        return text
    die("%s: anchor matched %d times" % (label, n))


def apply_palette(text):
    for old, new, label in (
        (PAL_OLD_TOKENS, PAL_NEW_TOKENS, "zen token block + surface rules"),
        (PAL_OLD_AMBIENT, PAL_NEW_AMBIENT, "zen ambient glass tints"),
        (PAL_OLD_PRESET, PAL_NEW_PRESET, "themePresets.zen (Mermaid)"),
        (PAL_OLD_SWATCH, PAL_NEW_SWATCH, "zen theme-menu swatch"),
    ):
        text = swap(text, old, new, label)
    return text


def apply_scene(text):
    if "Ryoan-ji from the veranda" in text:
        print("  = ambient scene: already applied")
        return text
    i_scenes = text.find("const AMBIENT_SCENES = {")
    if i_scenes == -1:
        die("scene: AMBIENT_SCENES not found")
    key = "\n        zen: {\n          settleFrames:"
    n = text.count(key, i_scenes)
    if n != 1:
        die("scene: zen entry key matched %d times inside AMBIENT_SCENES" % n)
    i_key = text.find(key, i_scenes) + 1  # first char of '        zen: {' line
    # walk back to the /* comment that precedes the entry
    i_cmt = text.rfind("/*", i_scenes, i_key)
    if i_cmt == -1 or i_key - i_cmt > 2500:
        die("scene: preceding /* comment not found near zen entry")
    closer = text.find("*/", i_cmt)
    if closer == -1 or closer > i_key:
        die("scene: comment does not close before zen entry")
    if "Zen" not in text[i_cmt:closer]:
        die("scene: preceding comment is not the Zen comment")
    i_start = text.rfind("\n", 0, i_cmt) + 1
    # walk forward to the entry's own closing brace at 8-space indent,
    # with or without trailing comma (last entry closes bare)
    m2 = re.search(r"^        \},?$", text[i_key:], re.M)
    if not m2:
        die("scene: closing brace not found after zen entry")
    i_end = i_key + m2.end()
    old_block = text[i_start:i_end]
    # guards: right block, right shape, no neighbour swallowed
    if not ("karesansui" in old_block or "Zen" in old_block[:600]):
        die("scene: unexpected zen block content")
    for neighbour in ("koi:", "matrix:", "sakura:", "tokyo:"):
        if neighbour in old_block:
            die("scene: block overran into neighbour %r" % neighbour)
    if old_block.count("init(") != 1 or old_block.count("draw(") != 1:
        die("scene: block has wrong shape (init/draw counts)")
    new_scene = SCENE.rstrip("\n")
    if not old_block.rstrip().endswith(","):
        # last entry in the object closed without a comma; keep it that way
        new_scene = new_scene.rstrip().rstrip(",")
    print("  + ambient scene: replaced %d chars with %d chars" % (len(old_block), len(new_scene)))
    return text[:i_start] + new_scene + text[i_end:]


def apply_intro(text):
    if "zi-enso" in text:
        print("  = intro overlay: already applied")
        return text
    # markup: zen overlay open tag up to (not including) the koi overlay
    m_start = '<div class="theme-intro-overlay zen-intro-overlay"'
    m_end = '<div class="theme-intro-overlay koi-intro-overlay"'
    if text.count(m_start) != 1:
        die("intro markup: zen overlay marker count = %d" % text.count(m_start))
    if text.count(m_end) != 1:
        die("intro markup: koi overlay marker count = %d" % text.count(m_end))
    i0 = text.index(m_start)
    i1 = text.index(m_end)
    if not (0 < i1 - i0 < 4000):
        die("intro markup: zen->koi span looks wrong (%d chars)" % (i1 - i0))
    text = text[:i0] + INTRO_HTML.rstrip().lstrip() + "\n  " + text[i1:]
    # css: the old zen block, replaced whole (its background-clip kanji rule must go)
    c_start = ".zen-intro-overlay { background: linear-gradient(165deg"
    c_end = ".zen-intro-overlay .theme-intro-progress i { background: linear-gradient(90deg, #4a5d43, #8d8a82); }"
    if text.count(c_start) != 1:
        die("intro css: old block start count = %d" % text.count(c_start))
    if text.count(c_end) != 1:
        die("intro css: old block end count = %d" % text.count(c_end))
    j0 = text.index(c_start)
    j1 = text.index(c_end) + len(c_end)
    if not (0 < j1 - j0 < 2000):
        die("intro css: old block span looks wrong (%d chars)" % (j1 - j0))
    text = text[: text.rindex("\n", 0, j0) + 1] + INTRO_CSS.rstrip("\n") + text[j1:]
    print("  + intro overlay: markup + css replaced")
    return text


def check_scripts(text):
    """node --check every inline <script> in the patched document."""
    scripts = re.findall(r"<script[^>]*>(.*?)</script>", text, re.S)
    scripts = [s for s in scripts if s.strip()]
    if not scripts:
        die("verify: no inline scripts found")
    try:
        for k, body in enumerate(scripts):
            fd, tmp = tempfile.mkstemp(suffix=".js")
            try:
                with io.open(fd, "w", encoding="utf-8", newline="") as f:
                    f.write(body)
                r = subprocess.run(["node", "--check", tmp],
                                   capture_output=True, text=True, shell=False)
                if r.returncode != 0:
                    sys.stderr.write(r.stderr)
                    return False
            finally:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass
        print("  + node --check: %d inline script(s) parse clean" % len(scripts))
        return True
    except FileNotFoundError:
        print("  ! node not found; syntax check skipped")
        return True


def main():
    if len(sys.argv) != 2:
        sys.exit("usage: python install_zen.py <target.html>")
    path = sys.argv[1]
    with io.open(path, "r", encoding="utf-8", newline="") as f:
        original = f.read()

    text = apply_palette(original)
    text = apply_scene(text)
    text = apply_intro(text)

    # final invariants
    for needle, label in (
        ('id="zenIntroOverlay"', "one zen intro overlay"),
        ("Ryoan-ji from the veranda", "scene installed"),
        ("--deco-gold: #a63c14", "palette installed"),
        ("zi-enso", "intro installed"),
    ):
        if needle == 'id="zenIntroOverlay"':
            if text.count(needle) != 1:
                die("invariant: %s (count=%d)" % (label, text.count(needle)))
        elif needle not in text:
            die("invariant: %s" % label)

    if text == original:
        print("OK: everything already installed in %s" % path)
        return

    with io.open(path, "w", encoding="utf-8", newline="") as f:
        f.write(text)
    if not check_scripts(text):
        with io.open(path, "w", encoding="utf-8", newline="") as f:
            f.write(original)
        die("verify: inline script failed node --check; original restored")
    print("OK: Zen Garden rework installed into %s (%d -> %d chars)"
          % (path, len(original), len(text)))


if __name__ == "__main__":
    main()
